def checkpoint(p,note=''):
 p=Path(p)
 return {'path':str(p),'local_status':'present' if p.exists() else ('dangling_symlink' if p.is_symlink() else 'not_at_inspected_local_path'),'bytes':p.stat().st_size if p.is_file() else None,'note':note}
def task(id,priority,panels,purpose,inputs,scripts,checks,actions,validation,deps,decision,outputs,notes):
 tasks.append(dict(id=id,priority=priority,panels=panels,purpose=purpose,inputs=[str(x) for x in inputs],scripts=[str(x) for x in scripts],checkpoints=[checkpoint(*x) if isinstance(x,tuple) else checkpoint(x) for x in checks],actions=actions,validation=validation,dependencies=deps,decision_needed=decision,public_outputs=outputs,availability_notes=notes))
